script:
% Preserve mission-name source Δ
Create Variable Keep I Count U Quantity Cost;
Keep = 41;
I = 0;
Count = 0;
U = 1;
Quantity = 0;
Cost = 0;
Create Spacecraft Sat;
Sat.DateFormat = A1ModJulian;
Sat.Epoch = 21545;
Sat.CoordinateSystem = EarthMJ2000Eq;
Sat.DisplayStateType = Cartesian;
Sat.X = 7000;
Sat.Y = 0;
Sat.Z = 0;
Sat.VX = 0;
Sat.VY = @SPEED@;
Sat.VZ = 0;
Create ForceModel FM;
FM.PrimaryBodies = {};
FM.PointMasses = {Earth};
FM.SRP = Off;
FM.Drag = None;
Create Propagator P;
P.FM = FM;
P.Type = RungeKutta89;
P.InitialStepSize = 10;
P.MinStep = 10;
P.MaxStep = 10;
P.Accuracy = 1e-12;
Create XYPlot Trace Control;
Trace.XVariable = Sat.ElapsedSecs;
Trace.YVariables = {Sat.ElapsedSecs};
Control.XVariable = Sat.ElapsedSecs;
Control.YVariables = {Sat.ElapsedSecs};
Create ReportFile Values Extra;
Values.Filename = '@VALUES@';
Extra.Filename = '@EXTRA@';
Values.WriteHeaders = false;
Values.FixedWidth = false;
Values.Delimiter = ',';
Values.Precision = 17;
Extra.WriteHeaders = false;
Extra.FixedWidth = false;
Extra.Precision = 17;
Sat.DateFormat = UTCGregorian;
Sat.Epoch = '01 Jan 2000 12:00:00.000';
Sat.NAIFId = -100070;
Sat.X = 7000;
Sat.Y = 0;
Sat.Z = 0;
Sat.VX = -0;
Sat.VY = 5.3358654506221255;
Sat.VZ = 5.3358654506221246;
SolarSystem.SPKFilename = '@DATA_ROOT@/planetary_ephem/spk/DE421AllPlanets.bsp';
Earth.EquatorialRadius = 6378.1365999999998;
Earth.Flattening = 0.0033528131084554717;
Create GroundStation East;
East.StateType = Spherical;
East.HorizonReference = Ellipsoid;
East.Location1 = -3.7405234971532204;
East.Location2 = 250.75384501373139;
East.Location3 = 1;
East.MinimumElevationAngle = 15;
Create ContactLocator Events;
Events.Target = Sat;
Events.Observers = {East};
Events.RunMode = Manual;
Events.ReportFormat = Legacy;
Events.WriteReport = true;
Events.UseEntireInterval = true;
Events.UseLightTimeDelay = false;
Events.UseStellarAberration = false;
Events.StepSize = 5;
Events.Filename = '@EVENT@';
BeginMissionSequence;
Propagate P(Sat) {Sat.ElapsedSecs = 6500};
FindEvents Events {Append = false};
Report 'Witness' Values Sat.ElapsedSecs Sat.EarthMJ2000Eq.X Sat.EarthMJ2000Eq.Y Sat.EarthMJ2000Eq.Z Sat.EarthMJ2000Eq.VX Sat.EarthMJ2000Eq.VY Sat.EarthMJ2000Eq.VZ Keep Count U Cost Quantity;
